import * as THREE from 'three';
import { buildWorld } from './world.js';
import { Enemy } from './enemy.js';
import { Weapon } from './weapon.js';
import { net } from './net.js';
import { RemotePlayer, BotProxy } from './remote.js';
import {
  unlockAudio, playHitmarker, playPlayerHit, playEnemyShot,
  playFootstep, playRicochet,
} from './audio.js';

// ---------- Renderer (tuned for performance) ----------
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.25)); // biggest FPS lever on high-DPI screens
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFShadowMap; // cheaper than PCFSoft
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
renderer.outputColorSpace = THREE.SRGBColorSpace;
document.getElementById('app').appendChild(renderer.domElement);

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.01, 120);
camera.rotation.order = 'YXZ';
scene.add(camera);

const world = buildWorld(scene);
const weapon = new Weapon(camera);

// one shared muzzle-flash light for ALL bots (per-bot lights wreck fragment shading cost)
const botFlash = new THREE.PointLight(0xffb066, 0, 9, 2);
scene.add(botFlash);

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

// ---------- Player / session state ----------
const HIP_FOV = 75, ADS_FOV = 52;
const EYE_STAND = 1.62, EYE_CROUCH = 1.08;

const player = {
  pos: world.playerSpawn.clone(),
  vel: new THREE.Vector3(),
  yaw: -Math.PI / 2,
  pitch: 0,
  lean: 0,
  eyeHeight: EYE_STAND,
  hp: 100,
  regenDelay: 0,
  bobPhase: 0,
  stepDist: 0,
  alive: true,
  crouching: false,
  moving: false,
};

const session = {
  mp: false,
  mode: 'solo',          // solo | coop | dm | dmbots
  isHost: true,
  myName: (localStorage.getItem('kh_name') || 'OPERATOR'),
  names: new Map(),      // id -> name
  remotes: new Map(),    // playerId -> RemotePlayer
  proxies: new Map(),    // botId -> BotProxy (non-host only)
  respawnTimer: 0,
  myKills: 0,
};

let gameState = 'menu';  // menu | mp | lobby | playing | over
let enemies = [];
const stats = { kills: 0, shots: 0, hits: 0, start: 0 };

const keys = {};
let mouseDX = 0, mouseDY = 0;
let firing = false, wantADS = false;

function myId() { return session.mp ? net.id : 0; }
function nameOf(id) {
  if (id === -1 || id == null) return 'HOSTILE';
  return session.names.get(id) || 'UNKNOWN';
}
const esc = s => String(s).replace(/[<>&]/g, c => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;' }[c]));
const r2 = v => Math.round(v * 100) / 100;

// ---------- UI refs ----------
const $ = id => document.getElementById(id);
const ui = {
  hud: $('hud'), crosshair: $('crosshair'), hitmarker: $('hitmarker'), vignette: $('vignette'),
  healthfill: $('healthfill'), magcount: $('magcount'), reservecount: $('reservecount'),
  ammo: $('ammo'), reloadhint: $('reloadhint'), enemycount: $('enemycount'),
  objectiveTitle: $('objective-title'), compassStrip: $('compass-strip'),
  killfeed: $('killfeed'), scores: $('scores'), respawn: $('respawn'), respawnSub: $('respawn-sub'),
  fps: $('fps'),
  nameInput: $('name-input'), codeInput: $('code-input'),
  menuErr: $('menu-err'), mpErr: $('mp-err'), lobbyHint: $('lobby-hint'),
  lobbyCode: $('lobby-code'), playerlist: $('playerlist'), btnStart: $('btn-start'),
  endTitle: $('end-title'), endStats: $('end-stats'),
};
const screens = ['menu', 'mp', 'lobby', 'end', 'gameover', 'victory', 'resume']
  .reduce((o, id) => (o[id] = $(id), o), {});

function showScreen(name) {
  for (const s of Object.values(screens)) s.classList.add('hidden');
  if (name) screens[name].classList.remove('hidden');
}

ui.nameInput.value = session.myName;
ui.nameInput.addEventListener('input', () => {
  session.myName = ui.nameInput.value.toUpperCase() || 'OPERATOR';
  localStorage.setItem('kh_name', session.myName);
});

// compass dial: 3 repetitions, 2px per degree
{
  const labels = { 0: 'N', 45: 'NE', 90: 'E', 135: 'SE', 180: 'S', 225: 'SW', 270: 'W', 315: 'NW' };
  let html = '';
  for (let d = 0; d < 1080; d += 15) {
    const text = labels[d % 360] !== undefined ? labels[d % 360] : '·';
    html += `<span style="position:absolute;left:${d * 2}px;transform:translateX(-50%)">${text}</span>`;
  }
  ui.compassStrip.innerHTML = html;
}

// ---------- Input ----------
window.addEventListener('keydown', e => {
  keys[e.code] = true;
  if (e.code === 'KeyR' && gameState === 'playing' && player.alive) weapon.startReload();
});
window.addEventListener('keyup', e => { keys[e.code] = false; });

document.addEventListener('mousemove', e => {
  if (document.pointerLockElement !== renderer.domElement) return;
  mouseDX += e.movementX;
  mouseDY += e.movementY;
});
document.addEventListener('mousedown', e => {
  if (document.pointerLockElement !== renderer.domElement) return;
  if (e.button === 0) firing = true;
  if (e.button === 2) wantADS = true;
});
document.addEventListener('mouseup', e => {
  if (e.button === 0) firing = false;
  if (e.button === 2) wantADS = false;
});
document.addEventListener('contextmenu', e => e.preventDefault());

function safeLock() {
  try {
    const p = renderer.domElement.requestPointerLock();
    if (p && p.catch) p.catch(() => {});
  } catch { /* needs a user gesture — the resume overlay handles it */ }
}

document.addEventListener('pointerlockchange', () => {
  const locked = document.pointerLockElement === renderer.domElement;
  if (locked) screens.resume.classList.add('hidden');
  else if (gameState === 'playing') screens.resume.classList.remove('hidden');
});
screens.resume.addEventListener('click', safeLock);

// ---------- Menu flow ----------
screens.menu.querySelector('#btn-solo').addEventListener('click', () => {
  unlockAudio();
  beginRound({
    mode: 'solo', host: 0, botCount: 8,
    players: [{ id: 0, name: session.myName, spawn: 0 }],
  });
});

screens.menu.querySelector('#btn-mp').addEventListener('click', async () => {
  unlockAudio();
  ui.menuErr.textContent = 'CONNECTING…';
  try {
    await net.connect();
    ui.menuErr.textContent = '';
    ui.mpErr.textContent = '';
    gameState = 'mp';
    showScreen('mp');
  } catch {
    ui.menuErr.textContent = 'SERVER OFFLINE — START THE GAME WITH "npm start"';
  }
});

$('btn-create').addEventListener('click', () => net.send({ t: 'create', name: session.myName }));
$('btn-join').addEventListener('click', () =>
  net.send({ t: 'join', code: ui.codeInput.value, name: session.myName }));
$('btn-mp-back').addEventListener('click', () => { gameState = 'menu'; showScreen('menu'); });

$('btn-leave').addEventListener('click', () => {
  net.send({ t: 'leave' });
  gameState = 'mp';
  showScreen('mp');
});
$('btn-start').addEventListener('click', () => { if (session.isHost) net.send({ t: 'start' }); });
for (const btn of document.querySelectorAll('.modebtn')) {
  btn.addEventListener('click', () => {
    if (session.isHost) net.send({ t: 'mode', mode: btn.dataset.mode });
  });
}

screens.end.addEventListener('click', () => { gameState = 'lobby'; showScreen('lobby'); });
screens.gameover.addEventListener('click', restartSolo);
screens.victory.addEventListener('click', restartSolo);
function restartSolo() {
  beginRound({
    mode: 'solo', host: 0, botCount: 8,
    players: [{ id: 0, name: session.myName, spawn: 0 }],
  });
}

// ---------- Lobby rendering ----------
let lastLobby = null;
function renderLobby(msg) {
  lastLobby = msg;
  session.isHost = msg.host === net.id;
  session.names.clear();
  for (const p of msg.players) session.names.set(p.id, p.name);

  ui.lobbyCode.textContent = msg.code;
  ui.playerlist.innerHTML = msg.players.map(p =>
    `<div>${p.id === msg.host ? '<span class="star">★</span> ' : ''}${esc(p.name)}${p.id === net.id ? ' — YOU' : ''}</div>`
  ).join('');
  for (const btn of document.querySelectorAll('.modebtn')) {
    btn.classList.toggle('active', btn.dataset.mode === msg.mode);
    btn.classList.toggle('locked', !session.isHost);
  }
  ui.btnStart.classList.toggle('disabled', !session.isHost);
  ui.lobbyHint.textContent = session.isHost
    ? '' : 'WAITING FOR HOST TO START';
}

// ---------- Net handlers ----------
net.on('err', msg => { ui.mpErr.textContent = msg.m; });

net.on('lobby', msg => {
  renderLobby(msg);
  if (gameState === 'mp' || gameState === 'lobby') {
    gameState = 'lobby';
    showScreen('lobby');
  } else if (gameState === 'playing') {
    // someone disconnected mid-match — drop their avatar
    const present = new Set(msg.players.map(p => p.id));
    for (const [id, rp] of session.remotes) {
      if (!present.has(id)) { rp.dispose(); session.remotes.delete(id); }
    }
  }
});

net.on('start', msg => beginRound(msg));

net.on('state', msg => session.remotes.get(msg.from)?.pushState(msg));

net.on('shoot', msg => {
  const from = new THREE.Vector3(...msg.f);
  tracerWithSound(from, new THREE.Vector3(...msg.e), 0xffe2a8);
  if (session.isHost) for (const e of enemies) e.hearGunshot(from);
});

net.on('hit', msg => {
  if (player.alive && session.mode !== 'coop') damagePlayer(msg.dmg, msg.from);
});

net.on('died', msg => {
  if (msg.scores) renderScores(msg.scores);
  addKillFeed(`${nameOf(msg.killer)} ▸ ${nameOf(msg.id)}`);
  if (msg.id !== net.id) session.remotes.get(msg.id)?.setDead();
  if (msg.killer === net.id && msg.id !== net.id) flashHitmarker(true);
});

net.on('respawn', msg => {
  session.remotes.get(msg.from)?.revive(msg.p[0], msg.p[1]);
});

net.on('bots', msg => {
  if (session.isHost) return;
  for (const s of msg.b) session.proxies.get(s[0])?.applyNet(s);
});

net.on('botShoot', msg => {
  const from = new THREE.Vector3(...msg.f);
  tracerWithSound(from, new THREE.Vector3(...msg.e), 0xffb09a);
  botFlash.position.copy(from);
  botFlash.intensity = 22;
  if (msg.target === net.id && msg.hit && player.alive) damagePlayer(msg.dmg, -1);
});

net.on('botDied', msg => {
  addKillFeed(`${nameOf(msg.by)} ▸ HOSTILE`);
  if (msg.by === net.id) flashHitmarker(true);
});

net.on('hitBot', msg => {
  if (!session.isHost) return;
  const e = enemies[msg.id];
  if (!e || !e.alive) return;
  const from = new THREE.Vector3(msg.sp[0], 1.4, msg.sp[1]);
  if (e.takeDamage(msg.dmg, from)) onBotKilled(msg.from);
});

net.on('end', msg => endMatch(msg));

net.on('close', () => {
  if (gameState === 'menu') return;
  cleanupRound();
  document.exitPointerLock();
  ui.hud.classList.remove('visible');
  gameState = 'menu';
  showScreen('menu');
  ui.menuErr.textContent = 'DISCONNECTED FROM SERVER';
});

// ---------- Round lifecycle ----------
function cleanupRound() {
  for (const e of enemies) e.dispose();
  enemies = [];
  for (const rp of session.remotes.values()) rp.dispose();
  session.remotes.clear();
  for (const bp of session.proxies.values()) bp.dispose();
  session.proxies.clear();
  for (const fx of effects) scene.remove(fx.obj);
  effects.length = 0;
  vignetteLevel = 0;
  session.respawnTimer = 0;
  ui.respawn.style.display = 'none';
  ui.killfeed.innerHTML = '';
}

function resetPlayerAt(spawn) {
  player.pos.set(spawn.x, 0, spawn.z);
  player.vel.set(0, 0, 0);
  // face the map center
  const d = spawn.clone().negate().normalize();
  player.yaw = Math.atan2(-d.x, -d.z);
  player.pitch = 0;
  player.hp = 100;
  player.alive = true;
  player.regenDelay = 0;
  weapon.group.visible = true;
}

function beginRound(info) {
  cleanupRound();
  session.mode = info.mode;
  session.mp = info.mode !== 'solo';
  session.isHost = !session.mp || info.host === net.id;
  session.myKills = 0;
  session.names.clear();
  for (const p of info.players) session.names.set(p.id, p.name);
  session.names.set(-1, 'HOSTILE');

  stats.kills = 0; stats.shots = 0; stats.hits = 0;
  stats.start = performance.now();

  const me = info.players.find(p => p.id === myId());
  resetPlayerAt(world.playerSpawns[(me ? me.spawn : 0) % world.playerSpawns.length]);
  weapon.mag = weapon.magSize;
  weapon.reserve = 120;
  weapon.reloading = 0;

  if (session.isHost) {
    for (let i = 0; i < info.botCount; i++) {
      enemies.push(new Enemy(scene, world.enemySpawns[i % world.enemySpawns.length], i));
    }
  } else {
    for (let i = 0; i < info.botCount; i++) {
      const spawn = world.enemySpawns[i % world.enemySpawns.length];
      session.proxies.set(i, new BotProxy(scene, i, spawn.pos));
    }
  }

  const kind = info.mode === 'coop' ? 'blue' : 'red';
  for (const p of info.players) {
    if (p.id === myId()) continue;
    const sp = world.playerSpawns[p.spawn % world.playerSpawns.length];
    session.remotes.set(p.id, new RemotePlayer(scene, p.id, p.name, kind, sp));
  }

  ui.objectiveTitle.textContent =
    session.mode === 'dm' ? 'DEATHMATCH — FIRST TO 10'
      : session.mode === 'dmbots' ? 'DM + BOTS — FIRST TO 10'
        : 'HOSTILES REMAINING';
  ui.scores.style.display = session.mp ? 'block' : 'none';
  if (session.mp) renderScores(info.players.map(p => ({ id: p.id, name: p.name, k: 0, d: 0 })));

  gameState = 'playing';
  showScreen(null);
  ui.hud.classList.add('visible');
  hudCache.clear();
  safeLock();
}

function endSolo(won) {
  gameState = 'over';
  document.exitPointerLock();
  ui.hud.classList.remove('visible');
  const secs = ((performance.now() - stats.start) / 1000).toFixed(1);
  const acc = stats.shots ? Math.round((stats.hits / stats.shots) * 100) : 0;
  const line = `${stats.kills} KILLS · ${acc}% ACCURACY · ${secs}s`;
  $(won ? 'victory-stats' : 'gameover-stats').textContent = line;
  showScreen(won ? 'victory' : 'gameover');
}

function endMatch(msg) {
  gameState = 'over';
  document.exitPointerLock();
  ui.hud.classList.remove('visible');
  cleanupRound();
  ui.endTitle.textContent =
    msg.reason === 'winner' ? `${nameOf(msg.winner)} WINS`
      : msg.reason === 'clear' ? 'AREA CLEAR'
        : msg.reason === 'hostleft' ? 'HOST LEFT'
          : 'MATCH OVER';
  const sorted = [...(msg.scores || [])].sort((a, b) => b.k - a.k);
  ui.endStats.innerHTML = sorted.map(s =>
    `${esc(s.name)} — ${s.k} KILLS / ${s.d} DEATHS`).join('<br>');
  showScreen('end');
}

// ---------- Effects ----------
const effects = [];
function pushEffect(fx) {
  effects.push(fx);
  if (effects.length > 90) {
    const old = effects.shift();
    scene.remove(old.obj);
  }
}

function addTracer(from, to, color = 0xffe2a8) {
  const geo = new THREE.BufferGeometry().setFromPoints([from, to]);
  const mat = new THREE.LineBasicMaterial({
    color, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false,
  });
  const line = new THREE.Line(geo, mat);
  scene.add(line);
  pushEffect({ obj: line, life: 0.07, maxLife: 0.07 });
}

function tracerWithSound(from, to, color) {
  addTracer(from, to, color);
  const dist = camera.position.distanceTo(from);
  const rel = from.clone().sub(camera.position).normalize();
  const right = new THREE.Vector3(1, 0, 0).applyQuaternion(camera.quaternion);
  playEnemyShot(dist, rel.dot(right));
}

function addImpact(point, normal) {
  const count = 6;
  const geo = new THREE.BufferGeometry();
  const positions = new Float32Array(count * 3);
  const velocities = [];
  for (let i = 0; i < count; i++) {
    positions[i * 3] = point.x; positions[i * 3 + 1] = point.y; positions[i * 3 + 2] = point.z;
    velocities.push(normal.clone()
      .add(new THREE.Vector3((Math.random() - 0.5) * 1.6, Math.random() * 1.2, (Math.random() - 0.5) * 1.6))
      .multiplyScalar(2 + Math.random() * 2));
  }
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  const pts = new THREE.Points(geo, new THREE.PointsMaterial({
    color: 0xc8bfae, size: 0.03, transparent: true, opacity: 0.9, depthWrite: false,
  }));
  scene.add(pts);
  pushEffect({
    obj: pts, life: 0.4, maxLife: 0.4,
    update(dt) {
      const p = pts.geometry.attributes.position;
      for (let i = 0; i < count; i++) {
        velocities[i].y -= 9.8 * dt;
        p.array[i * 3] += velocities[i].x * dt;
        p.array[i * 3 + 1] += velocities[i].y * dt;
        p.array[i * 3 + 2] += velocities[i].z * dt;
      }
      p.needsUpdate = true;
    },
  });
  const mark = new THREE.Mesh(
    new THREE.CircleGeometry(0.035, 8),
    new THREE.MeshBasicMaterial({ color: 0x14110e, transparent: true, opacity: 0.8 }));
  mark.position.copy(point).addScaledVector(normal, 0.004);
  mark.lookAt(point.clone().add(normal));
  scene.add(mark);
  pushEffect({ obj: mark, life: 6, maxLife: 6 });
}

function addBlood(point) {
  const mist = new THREE.Mesh(
    new THREE.SphereGeometry(0.09, 8, 8),
    new THREE.MeshBasicMaterial({ color: 0x6e0d0d, transparent: true, opacity: 0.7, depthWrite: false }));
  mist.position.copy(point);
  scene.add(mist);
  pushEffect({
    obj: mist, life: 0.25, maxLife: 0.25,
    update() { mist.scale.multiplyScalar(1.09); },
  });
}

// ---------- Shooting ----------
const raycaster = new THREE.Raycaster();
const _muzzle = new THREE.Vector3();
const _camDir = new THREE.Vector3();

weapon.onShot = (spread) => {
  stats.shots++;
  camera.getWorldDirection(_camDir);
  const dir = _camDir.clone();
  dir.x += (Math.random() - 0.5) * spread * 2;
  dir.y += (Math.random() - 0.5) * spread * 2;
  dir.z += (Math.random() - 0.5) * spread * 2;
  dir.normalize();

  raycaster.set(camera.getWorldPosition(new THREE.Vector3()), dir);
  raycaster.far = 100;

  const targets = [...world.solids.children];
  if (session.isHost) {
    for (const e of enemies) if (e.alive) targets.push(...e.hitboxes);
  } else {
    for (const bp of session.proxies.values()) if (bp.alive) targets.push(...bp.parts.hitboxes);
  }
  if (session.mode === 'dm' || session.mode === 'dmbots') {
    for (const rp of session.remotes.values()) if (rp.alive) targets.push(...rp.parts.hitboxes);
  }

  const hits = raycaster.intersectObjects(targets, false);
  weapon.muzzleWorldPos(_muzzle);
  let endPoint = raycaster.ray.at(100, new THREE.Vector3());

  if (hits.length > 0) {
    const hit = hits[0];
    endPoint = hit.point;
    const ud = hit.object.userData;
    const headshot = ud.part === 'head';
    const dmg = headshot ? 100 : 34;

    if (ud.enemy) {
      stats.hits++;
      addBlood(hit.point);
      playHitmarker();
      flashHitmarker(false);
      if (ud.enemy.takeDamage(dmg, player.pos)) onBotKilled(myId());
    } else if (ud.botId !== undefined) {
      stats.hits++;
      addBlood(hit.point);
      playHitmarker();
      flashHitmarker(false);
      net.send({ t: 'hitBot', id: ud.botId, dmg, sp: [r2(player.pos.x), r2(player.pos.z)] });
    } else if (ud.playerId !== undefined) {
      stats.hits++;
      addBlood(hit.point);
      playHitmarker();
      flashHitmarker(false);
      net.send({ t: 'hit', target: ud.playerId, dmg, head: headshot ? 1 : 0 });
    } else {
      const normal = hit.face
        ? hit.face.normal.clone().transformDirection(hit.object.matrixWorld)
        : dir.clone().negate();
      addImpact(hit.point, normal);
      if (Math.random() < 0.3) playRicochet(hit.distance);
    }
  }

  addTracer(_muzzle.clone(), endPoint);
  if (session.isHost) for (const e of enemies) e.hearGunshot(player.pos);
  if (session.mp) {
    net.send({
      t: 'shoot',
      f: [r2(_muzzle.x), r2(_muzzle.y), r2(_muzzle.z)],
      e: [r2(endPoint.x), r2(endPoint.y), r2(endPoint.z)],
    });
  }
};

function onBotKilled(byId) {
  stats.kills += (byId === myId()) ? 1 : 0;
  addKillFeed(`${nameOf(byId)} ▸ HOSTILE`);
  if (byId === myId()) flashHitmarker(true);
  if (session.mp) net.send({ t: 'botDied', by: byId });
  // bots cleared?
  if (enemies.length && enemies.every(e => !e.alive)) {
    if (session.mode === 'solo') endSolo(true);
    else if (session.mode === 'coop') net.send({ t: 'end', reason: 'clear' });
  }
}

// host-side bot fire resolution
function botFire(enemy, targetId, hit, dist) {
  const dmg = Math.round(6 + Math.random() * 8);
  const from = enemy.muzzle.getWorldPosition(new THREE.Vector3());
  const tgt = enemyCtx.targets.find(t => t.id === targetId);
  const aim = tgt ? tgt.eye.clone() : from.clone().add(new THREE.Vector3(0, 0, 1));
  aim.y -= 0.25;
  const to = hit ? aim : aim.add(new THREE.Vector3(
    (Math.random() - 0.5) * 2.4, (Math.random() - 0.5) * 1.6, (Math.random() - 0.5) * 2.4));

  tracerWithSound(from, to, 0xffb09a);
  botFlash.position.copy(from);
  botFlash.intensity = 22;

  if (targetId === myId() && hit && player.alive) damagePlayer(dmg, -1);
  if (session.mp) {
    net.send({
      t: 'botShoot',
      f: [r2(from.x), r2(from.y), r2(from.z)],
      e: [r2(to.x), r2(to.y), r2(to.z)],
      target: targetId, hit, dmg,
    });
  }
}

// ---------- Damage / death / respawn ----------
let vignetteLevel = 0;
let hitmarkerTimer = null;

function flashHitmarker(kill) {
  ui.hitmarker.style.opacity = 1;
  ui.hitmarker.classList.toggle('kill', kill);
  clearTimeout(hitmarkerTimer);
  hitmarkerTimer = setTimeout(() => { ui.hitmarker.style.opacity = 0; }, 120);
}

function addKillFeed(text) {
  const div = document.createElement('div');
  div.textContent = text;
  ui.killfeed.prepend(div);
  setTimeout(() => div.remove(), 4200);
  while (ui.killfeed.children.length > 5) ui.killfeed.lastChild.remove();
}

function damagePlayer(amount, killerId) {
  if (!player.alive) return;
  player.hp -= amount;
  player.regenDelay = 5;
  vignetteLevel = Math.min(1, vignetteLevel + 0.45);
  playPlayerHit();
  if (player.hp <= 0) {
    player.hp = 0;
    player.alive = false;
    firing = false;
    if (!session.mp) {
      endSolo(false);
    } else {
      net.send({ t: 'died', killer: killerId });
      weapon.group.visible = false;
      session.respawnTimer = session.mode === 'coop' ? 5 : 3;
      ui.respawn.style.display = 'block';
    }
  }
}

function respawnNow() {
  const sp = world.playerSpawns[Math.floor(Math.random() * world.playerSpawns.length)];
  resetPlayerAt(sp);
  weapon.mag = weapon.magSize;
  weapon.reserve = 120;
  weapon.reloading = 0;
  ui.respawn.style.display = 'none';
  net.send({ t: 'respawn', p: [r2(sp.x), r2(sp.z)] });
}

function renderScores(list) {
  const sorted = [...list].sort((a, b) => b.k - a.k);
  ui.scores.innerHTML = sorted.map(s =>
    `<div class="row${s.id === net.id ? ' me' : ''}"><span>${esc(s.name)}</span><span>${s.k} / ${s.d}</span></div>`
  ).join('');
  const mine = list.find(s => s.id === net.id);
  if (mine) session.myKills = mine.k;
}

// ---------- Player movement ----------
function collides(x, z, eyeH) {
  const r = 0.35;
  for (const box of world.colliders) {
    if (x + r > box.min.x && x - r < box.max.x &&
        z + r > box.min.z && z - r < box.max.z &&
        box.min.y < eyeH + 0.2 && box.max.y > 0.15) return true;
  }
  return false;
}

function updatePlayer(dt) {
  const sens = 0.0021 * (1 - weapon.adsAmount * 0.45);
  player.yaw -= mouseDX * sens;
  player.pitch -= mouseDY * sens;

  if (weapon.recoilKick > 0) {
    player.pitch += weapon.recoilKick;
    player.yaw += (Math.random() - 0.5) * weapon.recoilKick * 0.5;
    weapon.recoilKick = 0;
  }
  player.pitch = THREE.MathUtils.clamp(player.pitch, -Math.PI / 2 + 0.05, Math.PI / 2 - 0.05);

  let leanTarget = 0;
  if (keys.KeyQ) leanTarget = -1;
  else if (keys.KeyE) leanTarget = 1;
  player.lean += (leanTarget - player.lean) * Math.min(1, dt * 9);

  player.crouching = !!(keys.KeyC || keys.ControlLeft);
  const targetEye = player.crouching ? EYE_CROUCH : EYE_STAND;
  player.eyeHeight += (targetEye - player.eyeHeight) * Math.min(1, dt * 10);

  const fwd = (keys.KeyW ? 1 : 0) - (keys.KeyS ? 1 : 0);
  const strafe = (keys.KeyD ? 1 : 0) - (keys.KeyA ? 1 : 0);
  const sprinting = !!keys.ShiftLeft && fwd > 0 && !wantADS && !player.crouching;
  let speed = sprinting ? 5.4 : player.crouching ? 1.8 : 3.4;
  if (weapon.adsAmount > 0.5) speed *= 0.62;

  const sin = Math.sin(player.yaw), cos = Math.cos(player.yaw);
  const wishX = (-sin * fwd + cos * strafe);
  const wishZ = (-cos * fwd - sin * strafe);
  const len = Math.hypot(wishX, wishZ) || 1;
  const targetVX = (wishX / len) * speed * (fwd || strafe ? 1 : 0);
  const targetVZ = (wishZ / len) * speed * (fwd || strafe ? 1 : 0);
  player.vel.x += (targetVX - player.vel.x) * Math.min(1, dt * 11);
  player.vel.z += (targetVZ - player.vel.z) * Math.min(1, dt * 11);

  const nx = player.pos.x + player.vel.x * dt;
  if (!collides(nx, player.pos.z, player.eyeHeight)) player.pos.x = nx;
  else player.vel.x = 0;
  const nz = player.pos.z + player.vel.z * dt;
  if (!collides(player.pos.x, nz, player.eyeHeight)) player.pos.z = nz;
  else player.vel.z = 0;

  const hSpeed = Math.hypot(player.vel.x, player.vel.z);
  player.moving = hSpeed > 0.5;
  player.stepDist += hSpeed * dt;
  const stride = sprinting ? 2.2 : 1.7;
  if (player.stepDist > stride && player.moving) {
    player.stepDist = 0;
    playFootstep(sprinting);
  }
  player.bobPhase += hSpeed * dt * 1.6;
  const bob = Math.sin(player.bobPhase * 2) * 0.022 * Math.min(1, hSpeed / 3.4) * (1 - weapon.adsAmount * 0.7);

  const leanOffset = 0.38 * player.lean;
  camera.position.set(
    player.pos.x + cos * leanOffset,
    player.pos.y + player.eyeHeight + bob,
    player.pos.z - sin * leanOffset);
  camera.rotation.set(player.pitch, player.yaw, -player.lean * 0.19, 'YXZ');

  const targetFov = THREE.MathUtils.lerp(HIP_FOV, ADS_FOV, weapon.adsAmount) + (sprinting ? 4 : 0);
  if (Math.abs(camera.fov - targetFov) > 0.05) {
    camera.fov += (targetFov - camera.fov) * Math.min(1, dt * 12);
    camera.updateProjectionMatrix();
  }

  player.regenDelay -= dt;
  if (player.regenDelay <= 0 && player.hp < 100) {
    player.hp = Math.min(100, player.hp + dt * 4);
  }

  weapon.update(dt, {
    firing, wantADS, sprinting,
    moveSpeed: hSpeed,
    mouseDX, mouseDY,
  });

  mouseDX = 0;
  mouseDY = 0;
}

// ---------- HUD (cached writes — DOM churn is not free) ----------
const hudCache = new Map();
function setIf(key, value, fn) {
  if (hudCache.get(key) !== value) {
    hudCache.set(key, value);
    fn(value);
  }
}

function updateHUD() {
  setIf('hp', Math.round(player.hp), hp => {
    ui.healthfill.style.width = `${hp}%`;
    ui.healthfill.style.background = hp > 50
      ? 'linear-gradient(90deg,#57d973,#a8e063)'
      : hp > 25
        ? 'linear-gradient(90deg,#e0bd5f,#e8d28a)'
        : 'linear-gradient(90deg,#e05548,#e07a5f)';
  });
  setIf('mag', weapon.mag, v => { ui.magcount.textContent = v; });
  setIf('reserve', weapon.reserve, v => { ui.reservecount.textContent = `/ ${v}`; });
  setIf('low', weapon.mag <= 7, v => ui.ammo.classList.toggle('low', v));
  setIf('reload', weapon.reloading > 0, v => { ui.reloadhint.style.display = v ? 'block' : 'none'; });
  setIf('ads', weapon.adsAmount > 0.6, v => ui.crosshair.classList.toggle('ads', v));

  let count;
  if (session.mode === 'dm' || session.mode === 'dmbots') {
    count = `${session.myKills} / 10`;
  } else {
    count = session.isHost
      ? enemies.filter(e => e.alive).length
      : [...session.proxies.values()].filter(b => b.alive).length;
  }
  setIf('count', count, v => { ui.enemycount.textContent = v; });

  let heading = THREE.MathUtils.radToDeg(-player.yaw) % 360;
  if (heading < 0) heading += 360;
  ui.compassStrip.style.transform = `translateX(${160 - (heading + 360) * 2}px)`;

  vignetteLevel = Math.max(0, vignetteLevel - 0.016);
  const hurt = 1 - player.hp / 100;
  setIf('vig', Math.round((vignetteLevel + hurt * 0.45) * 40), v => {
    ui.vignette.style.opacity = Math.min(1, v / 40);
  });
}

// ---------- Main loop ----------
const clock = new THREE.Clock();
const enemyCtx = {
  targets: [],
  solids: world.solids,
  colliders: world.colliders,
  botFire,
  time: 0,
};

let stateTimer = 0, botTimer = 0;
let fpsFrames = 0, fpsTime = 0;

function buildTargets() {
  const t = enemyCtx.targets;
  t.length = 0;
  if (player.alive) t.push({ id: myId(), eye: camera.position, pos: player.pos });
  for (const [id, rp] of session.remotes) {
    if (rp.alive) t.push({ id, eye: rp.eyePos, pos: rp.group.position });
  }
}

function animate() {
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.05);
  const now = performance.now();

  if (gameState === 'playing') {
    if (player.alive) {
      updatePlayer(dt);
    } else if (session.mp) {
      session.respawnTimer -= dt;
      ui.respawnSub.textContent = `RESPAWNING IN ${Math.max(0, session.respawnTimer).toFixed(1)}`;
      if (session.respawnTimer <= 0) respawnNow();
      mouseDX = 0; mouseDY = 0;
    }

    buildTargets();
    enemyCtx.time = clock.elapsedTime;
    if (session.isHost) {
      for (const e of enemies) e.update(dt, enemyCtx);
    } else {
      for (const bp of session.proxies.values()) bp.tick(dt, now);
    }
    for (const rp of session.remotes.values()) rp.tick(dt, now);

    if (session.mp) {
      stateTimer -= dt;
      if (stateTimer <= 0 && player.alive) {
        stateTimer = 1 / 15;
        net.send({
          t: 'state',
          p: [r2(player.pos.x), r2(player.pos.z)],
          yaw: r2(player.yaw),
          c: player.crouching ? 1 : 0,
          m: player.moving ? 1 : 0,
        });
      }
      if (session.isHost) {
        botTimer -= dt;
        if (botTimer <= 0) {
          botTimer = 0.08;
          net.send({ t: 'bots', b: enemies.map(e => e.netState()) });
        }
      }
    }

    updateHUD();
  }

  botFlash.intensity *= Math.pow(0.0001, dt);

  for (let i = effects.length - 1; i >= 0; i--) {
    const fx = effects[i];
    fx.life -= dt;
    if (fx.update) fx.update(dt);
    if (fx.obj.material) fx.obj.material.opacity = Math.min(fx.obj.material.opacity ?? 1, fx.life / fx.maxLife);
    if (fx.life <= 0) {
      scene.remove(fx.obj);
      effects.splice(i, 1);
    }
  }

  const dustPos = world.dust.geometry.attributes.position;
  for (let i = 0; i < dustPos.count; i++) {
    let y = dustPos.getY(i) - dt * 0.06;
    if (y < 0) y = 4;
    dustPos.setY(i, y);
  }
  dustPos.needsUpdate = true;

  fpsFrames++;
  fpsTime += dt;
  if (fpsTime >= 0.5) {
    ui.fps.textContent = `${Math.round(fpsFrames / fpsTime)} FPS`;
    fpsFrames = 0;
    fpsTime = 0;
  }

  renderer.render(scene, camera);
}

animate();

// headless-verification mode: render the scene with HUD, no menu overlay
if (location.hash === '#screenshot') {
  showScreen(null);
  ui.hud.classList.add('visible');
  camera.position.set(player.pos.x, player.pos.y + player.eyeHeight, player.pos.z);
  camera.rotation.set(0, player.yaw, 0, 'YXZ');
  enemies.push(...world.enemySpawns.slice(0, 8).map((s, i) => new Enemy(scene, s, i)));
  updateHUD();
}
